  function normalizeRole(v){const raw=String(v||'').trim().toLowerCase();const map={administrator:'admin',director:'direktur','direktur pesantren':'direktur',pimpinan:'direktur',pengasuh:'direktur','wakil direktur':'wakil',wadir:'wakil',manager:'manajer','staff muda':'staf-muda','staff mula':'staf-mula','staf muda':'staf-muda','staf mula':'staf-mula','kepala sekolah':'kepala-sekolah','kepala sarpras':'sarpras',observer:'staf-muda','tim observer':'staf-muda','tim observasi':'staf-muda'};return map[raw]||raw}
  function rolesOf(u){let r=u?.allRoles??u?.roles??u?.jabatan??u?.akses??u?.role??[];if(!Array.isArray(r))r=[r];return uniq(r.flatMap(x=>String(x||'').split(/[;,|]/)).map(normalizeRole))}
