  function signalChip(s){const cls=s==='green'?'green':s==='red'?'red':'gold',label=s==='green'?'Baik':s==='red'?'Perlu Tindakan':'Perlu Perhatian';return `<span class="chip ${cls}">${label}</span>`}
  function empty(t){return `<div class="empty">${esc(t)}</div>`}
  function recordCard({chips=[],date='',title='',desc='',foot='',onclick=''}){return `<article class="item-card" ${onclick?`onclick="${onclick}"`:''}><div class="item-top"><div class="chips">${chips.join('')}</div><span class="date">${esc(date)}</span></div><h3>${esc(title)}</h3>${desc?`<p>${esc(desc)}</p>`:''}${foot?`<div class="item-foot">${foot}</div>`:''}</article>`}
  function divisionOptions(selected='',all=true){return `${all?'<option value="Semua Divisi">Semua Divisi</option>':''}${DIVISIONS.filter(x=>x!=='Semua Divisi').map(x=>`<option value="${esc(x)}" ${x===selected?'selected':''}>${esc(x)}</option>`).join('')}`}
  function levelOptions(selected=''){return Object.entries(LEVELS).map(([k,v])=>`<option value="${k}" ${k===selected?'selected':''}>${v.label}</option>`).join('')}
