      const agenda=[];if(upcoming)agenda.push([`${MEETING_LABELS[upcoming.meetingType]||'Rapat'} • ${upcoming.title||''}`,`${fmtDate(upcoming.date)}${upcoming.time?' • '+upcoming.time:''}`]);overdue.slice(0,3).forEach(x=>agenda.push([`Terlambat: ${x.title||x.task||'Tugas'}`,`PIC ${x.picName||x.pic||'-'} • ${fmtDate(x.deadline)}`]));const info=LEVELS[currentLevel()]||LEVELS['staf-mula'];agenda.push([`${info.report}${currentDivision()!=='Semua Divisi'?' — '+currentDivision():''}`,`Ritme: ${info.cadence}`]);$('managementAgenda').innerHTML=agenda.map((x,i)=>`<div class="mandate-item"><i>${i+1}</i><div><b>${esc(x[0])}</b><span>${esc(x[1])}</span></div></div>`).join('');
